import{_ as e,o as l,c as r,a2 as n}from"./chunks/framework.CZGNF-7T.js";const x=JSON.parse('{"title":"수수료 정책 관리","description":"","frontmatter":{},"headers":[],"relativePath":"sales/policy.md","filePath":"sales/policy.md","lastUpdated":1788790735000}'),a={name:"sales/policy.md"};function d(s,t,o,i,g,c){return l(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="수수료-정책-관리" tabindex="-1">수수료 정책 관리 <a class="header-anchor" href="#수수료-정책-관리" aria-label="Permalink to &quot;수수료 정책 관리&quot;">​</a></h1><p>프로젝트의 차수(OrderGroup) 및 유니트 타입(UnitType)별로 적용할 영업 직책별 수수료(상담사, 팀장, 본부장 R값)와 MGM 소개 수수료를 사전에 매트릭스로 책정하는 기준 정책 관리 페이지입니다.</p><ul><li><strong>위치</strong>: <code>PJT 관리 시스템 &gt; 분양 대행 관리 &gt; 수수료 정책 관리</code></li></ul><h2 id="개요" tabindex="-1">개요 <a class="header-anchor" href="#개요" aria-label="Permalink to &quot;개요&quot;">​</a></h2><p>분양 성공 시 영업 인력에게 지급할 성과급(인센티브 R값)의 기준표를 사전에 정의합니다. 주거용, 상업용 등 유니트 타입이나 차수에 따라 건당 수수료 금액이 상이하므로, 이를 매트릭스 형태로 등록하여 계약 체결 시 정확한 수수료가 자동으로 계산되도록 지원합니다. 상담사 개인 수수료뿐만 아니라 관리 조직인 팀장 및 본부장의 오버라이딩 수수료, 외부 공인중개사 유치 시 지급할 MGM 소개료까지 하나의 정책으로 통합 관리합니다.</p><h2 id="주요-기능" tabindex="-1">주요 기능 <a class="header-anchor" href="#주요-기능" aria-label="Permalink to &quot;주요 기능&quot;">​</a></h2><ul><li><strong>차수 및 타입별 수수료 매트릭스</strong>: 프로젝트 차수와 유니트 타입별 개별 정책 등록</li><li><strong>직책별 차등 수수료(R값) 설정</strong>: <ul><li>담당 상담사 건당 수수료 (<code>agent_fee</code>)</li><li>팀장 건당 수수료 (<code>leader_fee</code>)</li><li>본부장 건당 수수료 (<code>director_fee</code>)</li></ul></li><li><strong>MGM 연계 수수료 설정</strong>: 공인중개사 소개 시 지급할 MGM 수당 (<code>mgm_fee</code>)</li><li><strong>수수료 지급 조건 설정</strong>: 계약금 완납 시 100%, 1/2차 분할 지급, 공급계약 체결 시 등 지급 조건 명시</li><li><strong>적용 유효 기간 및 활성 상태 관리</strong>: 시작일/종료일 지정 및 정책 활성화 토글</li><li><strong>통계 요약 카드 제공</strong>: 등록된 정책 수, 평균 상담사 수수료, 최고 수수료, 최저 수수료 한눈에 파악</li></ul><h2 id="화면-구성" tabindex="-1">화면 구성 <a class="header-anchor" href="#화면-구성" aria-label="Permalink to &quot;화면 구성&quot;">​</a></h2><h3 id="_1-상단-수수료-정책-요약-카드" tabindex="-1">1. 상단 수수료 정책 요약 카드 <a class="header-anchor" href="#_1-상단-수수료-정책-요약-카드" aria-label="Permalink to &quot;1. 상단 수수료 정책 요약 카드&quot;">​</a></h3><ul><li><strong>총 등록 정책 수</strong>: 현재 프로젝트에 등록된 수수료 정책 건수</li><li><strong>평균 상담사 수수료</strong>: 등록된 정책들의 상담사 평균 건당 수수료 금액</li><li><strong>최고 수수료</strong>: 가장 높은 금액으로 책정된 유니트 타입의 수수료</li><li><strong>최저 수수료</strong>: 가장 낮은 금액으로 책정된 유니트 타입의 수수료</li></ul><h3 id="_2-수수료-정책-목록-및-필터-바" tabindex="-1">2. 수수료 정책 목록 및 필터 바 <a class="header-anchor" href="#_2-수수료-정책-목록-및-필터-바" aria-label="Permalink to &quot;2. 수수료 정책 목록 및 필터 바&quot;">​</a></h3><ul><li><strong>차수 필터</strong>: 특정 분양 차수별 필터링</li><li><strong>타입 필터</strong>: 특정 유니트 타입별 필터링</li><li><strong>검색창</strong>: 정책명 키워드 검색</li><li><strong>[신규 정책 등록] 버튼</strong>: 새로운 수수료 기준표를 등록하는 모달 호출 (<code>primary</code>)</li></ul><h3 id="_3-수수료-정책-대장-테이블" tabindex="-1">3. 수수료 정책 대장 테이블 <a class="header-anchor" href="#_3-수수료-정책-대장-테이블" aria-label="Permalink to &quot;3. 수수료 정책 대장 테이블&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">항목</th><th style="text-align:left;">설명</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>정책명</strong></td><td style="text-align:left;">정책 명칭 (예: &quot;1차 84A타입 기본 수수료&quot;)</td></tr><tr><td style="text-align:left;"><strong>적용 차수 / 타입</strong></td><td style="text-align:left;">해당 정책이 적용되는 차수 그룹 및 유니트 타입</td></tr><tr><td style="text-align:left;"><strong>상담사 수수료</strong></td><td style="text-align:left;">계약 성사 상담사에게 지급되는 건당 인센티브 금액</td></tr><tr><td style="text-align:left;"><strong>팀장 수수료</strong></td><td style="text-align:left;">해당 팀의 팀장에게 귀속되는 오버라이딩 수수료</td></tr><tr><td style="text-align:left;"><strong>본부장 수수료</strong></td><td style="text-align:left;">상위 본부장에게 귀속되는 오버라이딩 수수료</td></tr><tr><td style="text-align:left;"><strong>MGM 소개료</strong></td><td style="text-align:left;">외부 공인중개사 소개 성약 시 지급되는 건당 수수료</td></tr><tr><td style="text-align:left;"><strong>지급 조건</strong></td><td style="text-align:left;">계약금 100% 완납, 분할 지급 등 설정된 지급 조건</td></tr><tr><td style="text-align:left;"><strong>적용 기간</strong></td><td style="text-align:left;">정책의 효력이 유지되는 유효 기간 (시작일 ~ 종료일)</td></tr><tr><td style="text-align:left;"><strong>상태</strong></td><td style="text-align:left;">활성(초록 뱃지) 또는 비활성(회색 뱃지)</td></tr><tr><td style="text-align:left;"><strong>관리</strong></td><td style="text-align:left;">행별 수정(<code>[연필]</code>, <code>success</code>) 및 삭제(<code>[휴지통]</code>, <code>danger</code>) 버튼</td></tr></tbody></table><h3 id="_4-수수료-정책-등록-수정-모달-policyformmodal" tabindex="-1">4. 수수료 정책 등록/수정 모달 (PolicyFormModal) <a class="header-anchor" href="#_4-수수료-정책-등록-수정-모달-policyformmodal" aria-label="Permalink to &quot;4. 수수료 정책 등록/수정 모달 (PolicyFormModal)&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">입력 항목</th><th style="text-align:center;">필수 여부</th><th style="text-align:left;">설명 및 비고</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>정책명</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">식별하기 쉬운 수수료 정책 이름</td></tr><tr><td style="text-align:left;"><strong>적용 차수</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">특정 차수에 한정할 경우 선택 (미선택 시 전체 차수)</td></tr><tr><td style="text-align:left;"><strong>적용 유니트 타입</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">특정 평형/타입에 한정할 경우 선택</td></tr><tr><td style="text-align:left;"><strong>상담사 수수료 (원)</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">담당 상담사 건당 지급액</td></tr><tr><td style="text-align:left;"><strong>팀장 수수료 (원)</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">팀장 오버라이딩 수당</td></tr><tr><td style="text-align:left;"><strong>본부장 수수료 (원)</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">본부장 오버라이딩 수당</td></tr><tr><td style="text-align:left;"><strong>MGM 소개 수수료 (원)</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">공인중개사 연계 시 건당 소개료</td></tr><tr><td style="text-align:left;"><strong>지급 조건</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">1. 완납 시 전액, 2. 분할 지급, 3. 공급계약 체결 시, 4. 청약 시</td></tr><tr><td style="text-align:left;"><strong>적용 시작일</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">정책 효력 시작 일자 (<code>DatePicker</code>)</td></tr><tr><td style="text-align:left;"><strong>적용 종료일</strong></td><td style="text-align:center;">선택</td><td style="text-align:left;">정책 종료 일자 (<code>DatePicker</code>, 무기한 시 공란)</td></tr><tr><td style="text-align:left;"><strong>활성화 여부</strong></td><td style="text-align:center;">필수</td><td style="text-align:left;">체크박스를 통해 현재 적용 여부 설정</td></tr></tbody></table>',16)])])}const f=e(a,[["render",d]]);export{x as __pageData,f as default};
